contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint dep, uint col) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        // Constrain the collected amount to be more than the deposit but less than MinSum,
        // so that the Collect condition cannot be satisfied.
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        require(col > dep);
        require(col < minSumBefore);
        require(dep > 0);          // a positive deposit so the balance is non-zero
        require(address(this).balance >= dep);

        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;
        uint balAfterDep = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfterDep = address(c).balance;

        bool reverted;
        c.Collect(col); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        // The guard `balances[msg.sender] >= _am` is false (since dep < col),
        // so the call does nothing and must not revert.
        // Hence the state must remain exactly as it was after the deposit.
        assert(!reverted && c.balances(address(this)) == balAfterDep && address(c).balance == cBalAfterDep);
    }

    receive() external payable {}
}

