// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 dep, uint256 col) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        vm.assume(col > dep);
        vm.assume(col < minSumBefore);
        vm.assume(dep > 0);
        vm.assume(address(this).balance >= dep);
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 balAfterDep;
        try c.balances(address(this)) returns (uint256 __r) { balAfterDep = __r; } catch { return; }
        uint cBalAfterDep = address(c).balance;
        bool reverted;
        try c.Collect(col) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == balAfterDep && address(c).balance == cBalAfterDep);
    }

    function testFuzz_run(uint256 dep, uint256 col) public {
        _run(dep, col);
    }

    receive() external payable {}
}
